import * as M from './model.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const number=n=>Number(n).toLocaleString('ko-KR');
export const grade=g=>M.GRADES[g]||M.GRADES['일반'];
export const screenInfo={world:['아덴 대륙','',''],menu:['전체 메뉴','YOUR ADVENTURE','원하는 기능을 선택하세요.'],transform:['변신','TRANSFORMATION','새로운 모습으로, 더 강한 힘으로.'],doll:['마법인형','MAGIC DOLL','모험을 함께하는 작은 동반자.'],relic:['성물','SACRED RELIC','영웅의 흔적에 깃든 힘.'],collection:['컬렉션','COLLECTION','수집한 기록이 힘이 됩니다.'],inventory:['인벤토리','INVENTORY','한 번 눌러 선택 · 두 번 눌러 사용 또는 장착'],character:['캐릭터','CHARACTER','황혼의 기사 · 장비와 전투 정보'],stats:['스탯','ATTRIBUTES','능력치를 배분하고 변화를 확인하세요.'],skills:['스킬','SKILLS','배우고, 사용하고, 퀵슬롯에 등록하세요.'],forge:['강화','ENCHANTMENT','장비에 새로운 힘을 더하세요.'],craft:['제작','CRAFTING','재료를 모아 필요한 물품을 만드세요.'],storage:['창고','STORAGE','장비와 소모품을 보관하세요.'],shop:['상점','SUPPLIES','다음 모험을 위한 준비.'],settings:['설정','PREFERENCES','보기 편하고 누르기 편한 화면으로.']};
const paths={menu:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h6v6h-6z',transform:'M12 2 20 6v8l-8 8-8-8V6z M8 9l3 2 M16 9l-3 2 M9 16h6',doll:'M8 8a4 4 0 1 1 8 0v4l4 7-5-1-3 4-3-4-5 1 4-7z M9 9h.1 M15 9h.1',relic:'M12 2 17 8l-5 12-5-12z M2 8h20 M6 4l-4 4 10 14L22 8l-4-4',collection:'M4 3h6l2 2 2-2h6v17h-6l-2 1-2-1H4z M12 5v16 M7 8h2 M15 8h2 M7 12h2 M15 12h2',inventory:'M5 8h14l2 13H3z M8 8V6a4 4 0 0 1 8 0v2 M8 12v3 M16 12v3',character:'M12 3a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M4 22v-3a8 8 0 0 1 16 0v3',stats:'M4 20V12h4v8 M10 20V8h4v12 M16 20V3h4v17',skills:'m13 2-8 12h6l-1 8 9-13h-6z',forge:'m14 3 7 7-4 4-3-3L5 21l-3-3 10-9-3-3z M17 1l6 6',craft:'M3 20 20 3 M15 3h5v5 M4 4l5 5 M4 2v4H2 M19 17v5 M16 20h6',storage:'M3 7 12 2l9 5v14H3z M3 7h18 M7 12h10 M7 16h10',shop:'M3 4h18l1 6H2z M4 10v11h16V10 M8 21v-7h8v7',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M9 2h6l1 4 4 1 2 5-3 3v5l-5 2-3-3-5 1-3-5 2-4-1-5z',close:'m6 6 12 12 M18 6 6 18',back:'m14 5-7 7 7 7',next:'m9 5 7 7-7 7',plus:'M12 5v14 M5 12h14',minus:'M5 12h14',check:'m4 12 5 5L20 6',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4',star:'m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',search:'M10 3a7 7 0 1 1 0 14 7 7 0 0 1 0-14 M15 15l7 7',reset:'M4 7v6h6 M5 12a8 8 0 1 1 2 6',info:'M12 11v6 M12 7h.01 M12 2a10 10 0 1 1 0 20 10 10 0 0 1 0-20',coin:'M12 3a9 9 0 1 1 0 18 9 9 0 0 1 0-18 M15 8h-5v4h4v4H9 M12 6v12',arrow:'M4 12h16 M15 7l5 5-5 5'};
export const icon=(id,cl='')=>`<svg class="icon ${cl}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.relic}"/></svg>`;
export const btn=(text,action,opts={})=>`<button type="button" class="button ${opts.class||'secondary'}" data-action="${action}" ${opts.id?`data-id="${esc(opts.id)}"`:''} ${opts.disabled?'disabled':''} ${opts.extra||''}>${opts.icon?icon(opts.icon):''}${text}</button>`;
export const iconBtn=(id,action,label,extra='')=>`<button type="button" class="icon-button" data-action="${action}" aria-label="${label}" title="${label}" ${extra}>${icon(id)}</button>`;
export const image=(src,alt='',cl='')=>`<img src="${esc(src)}" alt="${esc(alt)}" class="${cl}" draggable="false">`;
export const line=(label,value,cl='')=>`<div class="stat-line ${cl}"><span>${label}</span><b>${value}</b></div>`;
export const pill=(text,cl='')=>`<span class="pill ${cl}">${text}</span>`;
export const empty=(title,detail='')=>`<div class="empty-state">${icon('search')}<h3>${title}</h3><p>${detail}</p></div>`;
export const tabs=(list,active,action)=>`<div class="tabs" role="tablist">${list.map(([id,label])=>`<button type="button" class="tab-button ${active===id?'active':''}" role="tab" aria-selected="${active===id}" data-action="${action}" data-id="${id}">${label}</button>`).join('')}</div>`;
export const chips=(list,active,action)=>`<div class="filter-row">${list.map(label=>`<button type="button" class="chip ${label===active?'active':''}" aria-pressed="${label===active}" data-action="${action}" data-id="${label}">${label}</button>`).join('')}</div>`;
export const search=(name,value,placeholder)=>`<label class="search-field">${icon('search')}<input class="search-input" type="search" name="${name}" value="${esc(value)}" placeholder="${placeholder}" aria-label="${placeholder}" autocomplete="off"></label>`;
export function itemSlot(item,action='select-item',selected=false){return `<button class="item-slot ${selected?'selected':''} ${item.equipped?'equipped':''}" data-action="${action}" data-id="${item.id}" aria-label="${esc(M.displayItem(item))}${item.equipped?' 장착 중':''}${item.locked?' 잠김':''}, ${item.count}개" aria-pressed="${selected}" style="--grade:${grade(item.grade)}">${image(item.art,item.name)}${['weapon','armor'].includes(item.type)?`<span class="item-enchant">+${item.enchant}</span>`:''}${item.equipped?'<span class="item-mark">E</span>':''}${item.locked?`<span class="item-lock">${icon('lock')}</span>`:''}${item.count>1?`<span class="item-count">${item.count}</span>`:''}</button>`;}
